// Одноразовый переход со старой v12: первые 55 слов были личными,
// остальные добавились через тематические блоки. Их переносим в отдельный прогресс блоков.
if (localStorage.getItem('citajSrpskiSeparateVocabV13') !== '1') {
  if (saved.length > 55) {
    const oldSaved = saved.slice(55);
    const migrated = oldSaved.map(x => {
      const block = x.blockId || VOCAB_BLOCKS.find(b => b.words.some(v => v.word === x.word))?.id;
      return {word:x.word, blockId:block, box:Math.min(6,Math.max(1,Number(x.box)||1)), nextReview:x.nextReview || Date.now()};
    }).filter(x => x.blockId);
    vocabProgress = [...vocabProgress, ...migrated];
    saved = saved.map(x => ({...x, blockId:undefined}));
  } else {
    saved = saved.map(x => ({...x, blockId:undefined}));
  }
  localStorage.setItem('citajSrpskiSeparateVocabV13','1');
  localStorage.setItem('citajSrpskiVocabProgress', JSON.stringify(vocabProgress));
  localStorage.setItem('citajSrpskiWords', JSON.stringify(saved));
}

