function isLikelyRussianTranslation(value){
  const t=String(value||'').trim();
  if(!t) return false;
  // Сербский/английский ответ от внешнего сервиса не должен попадать в русский словарь.
  // Разрешаем цифры, латинские буквы внутри примечаний и знаки препинания,
  // но требуем хотя бы одну кириллическую букву.
  return /[А-Яа-яЁё]/.test(t);
}
const REMOTE_TRANSLATION_CACHE = (()=>{
  try{
    const raw=JSON.parse(localStorage.getItem('citajSrpskiRemoteTranslations')||'{}')||{};
    let changed=false;
    Object.keys(raw).forEach(k=>{if(!isLikelyRussianTranslation(raw[k])){delete raw[k];changed=true;}});
    if(changed) localStorage.setItem('citajSrpskiRemoteTranslations',JSON.stringify(raw));
    return raw;
  }catch(e){return {};}
})();
function saveRemoteTranslationCache(){
  try{localStorage.setItem('citajSrpskiRemoteTranslations',JSON.stringify(REMOTE_TRANSLATION_CACHE));}catch(e){}
}

function getTranslation(w){
  const n=normalize(w);
  if(CONTEXT_TRANSLATIONS[n]) return CONTEXT_TRANSLATIONS[n];
  if(LOCAL_TRANSLATION_FALLBACK[n]) return LOCAL_TRANSLATION_FALLBACK[n];
  if(DICT[n]) return DICT[n];
  const verb=findVerbInfo(n);
  if(verb && verb.translation) return verb.translation;
  if(REMOTE_TRANSLATION_CACHE[n]) return REMOTE_TRANSLATION_CACHE[n];
  const candidates=[];
  const suffixes=['ovima','evima','ama','ima','anje','enje','u','om','em','og','oj','im','as','os','es','us','a','e','i','o','y'];
  for(const suffix of suffixes){
    if(n.length>suffix.length+2 && n.endsWith(suffix)) candidates.push(n.slice(0,-suffix.length));
  }
  for(const c of candidates){ if(DICT[c]) return `${DICT[c]} (форма слова «${n}»)`; }
  return 'Перевод загружается…';
}

let translationRequestId=0;
async function preloadTextTranslations(text){
  const words=[...new Set((String(text||'').match(/[\p{L}\p{M}\p{N}]+(?:['’][\p{L}\p{M}\p{N}]+)?/gu)||[]).map(normalize).filter(Boolean))];
  const missing=words.filter(w=>getTranslation(w)==='Перевод загружается…');
  let cursor=0;
  const worker=async()=>{
    while(cursor<missing.length){
      const w=missing[cursor++];
      try{await remoteTranslateWord(w);}catch(e){}
    }
  };
  // Несколько последовательных запросов на каждом воркере не перегружают бесплатные API.
  await Promise.all(Array.from({length:4},worker));
  return missing.length;
}

async function remoteTranslateWord(w){
  const n=normalize(w);
  if(!n || DICT[n] || REMOTE_TRANSLATION_CACHE[n]) return getTranslation(n);
  const urls=[
    {url:`https://api.mymemory.translated.net/get?q=${encodeURIComponent(n)}&langpair=sr|ru`, type:'mymemory'},
    {url:`https://api.mymemory.translated.net/get?q=${encodeURIComponent(n)}&langpair=sr-Latn|ru`, type:'mymemory'},
    {url:`https://translate.googleapis.com/translate_a/single?client=gtx&sl=sr&tl=ru&dt=t&q=${encodeURIComponent(n)}`, type:'google'}
  ];
  for(const item of urls){
    try{
      const r=await fetch(item.url,{headers:{Accept:'application/json'}});
      if(!r.ok) continue;
      const j=await r.json();
      const tr=item.type==='google' ? String(j?.[0]?.[0]?.[0]||'').trim() : String(j?.responseData?.translatedText||'').trim();
      if(tr && isLikelyRussianTranslation(tr) && !/INVALID TARGET LANGUAGE|MYMEMORY|quota|error/i.test(tr)){
        REMOTE_TRANSLATION_CACHE[n]=tr;
        saveRemoteTranslationCache();
        return tr;
      }
    }catch(e){}
  }
  return getTranslation(n);
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}



