function vocabBlock(id){ return VOCAB_BLOCKS.find(b=>b.id===id); }
function blockProgress(id){ return vocabProgress.filter(x=>x.blockId===id); }
function saveVocabProgress(){ localStorage.setItem('citajSrpskiVocabProgress',JSON.stringify(vocabProgress)); }
function addVocabWord(item, blockId){
  if(!vocabProgress.some(x=>x.word===item.word && x.blockId===blockId)){
    vocabProgress.push({word:item.word,blockId,box:1,nextReview:Date.now()});
    saveVocabProgress();
  }
}
function addWholeBlock(id){
  const b=vocabBlock(id); if(!b) return;
  b.words.forEach(x=>addVocabWord(x,id));
  saveVocabProgress(); vocab();
}
function startBlockReview(id, mode="choice"){
  const b=vocabBlock(id); if(!b) return;
  let list=blockProgress(id);
  if(!list.length){
    addWholeBlock(id);
    list=blockProgress(id);
  }
  // blockProgress stores only progress; merge it with the source vocabulary
  // so training always has a real translation instead of undefined.
  list=list.map(p=>{
    const source=b.words.find(x=>x.word===p.word);
    return source ? {...p, translation:source.translation} : p;
  }).filter(x=>x && x.translation);
  exerciseType=mode==='reverse'?'reverse':'choice';
  exercisePool=list;
  exerciseQueue=shuffle(list).slice(0,Math.min(20,list.length)).map(x=>x.word);
  exerciseIndex=0;
  renderExercise();
  view('review');
}
function vocab(){
  $('vocab-list').innerHTML=VOCAB_BLOCKS.map(b=>{
    const count=blockProgress(b.id).length;
    return `<div class="card vocab-card">
      <div class="tag">${b.level}</div>
      <h3>${b.title}</h3>
      <p class="muted">${b.description}</p>
      <p><b>${b.words.length} слов</b> · в учебном прогрессе: <b>${count}</b></p>
      <div class="vocab-actions">
        <button type="button" class="vocab-add" data-block="${b.id}">＋ Изучать весь блок</button>
        <button type="button" class="vocab-review" data-block="${b.id}" data-mode="choice">🔁 Сербское → русский</button>
        <button type="button" class="vocab-review" data-block="${b.id}" data-mode="reverse">🔄 Русское → сербское</button>
      </div>
      <details><summary>Показать слова</summary><div class="vocab-list">${b.words.map((x,i)=>{
        const active=blockProgress(b.id).some(s=>s.word===x.word);
        return `<div class="vocab-row"><span>${i+1}. <b>${x.word}</b></span><span>${x.translation}</span><button type="button" class="vocab-one" data-block="${b.id}" data-word="${x.word}">${active?'✓':'＋'}</button></div>`;
      }).join('')}</div></details>
    </div>`;
  }).join('');
  view('vocab');
  document.querySelectorAll('.vocab-add').forEach(btn=>btn.addEventListener('click',()=>addWholeBlock(btn.dataset.block)));
  document.querySelectorAll('.vocab-review').forEach(btn=>btn.addEventListener('click',()=>startBlockReview(btn.dataset.block, btn.dataset.mode || 'choice')));
  document.querySelectorAll('.vocab-one').forEach(btn=>btn.addEventListener('click',()=>{
    const b=vocabBlock(btn.dataset.block); const item=b?.words.find(x=>x.word===btn.dataset.word);
    if(item){addVocabWord(item,b.id);vocab();}
  }));
}

function texts(filterLevel="all"){
  // Краеведческие материалы о Суботице находятся только в разделе «Краеведение».
  // В «Текстах» показываем учебную библиотеку A1/A2 и исторические оригиналы.
  const allLocal=TEXTS.filter(t=>!t.level.includes('Исторический') && t.category!=='subotica');
  const historical=TEXTS.filter(t=>t.level.includes('Исторический'));
  const local=filterLevel==='A1' ? allLocal.filter(t=>/^A1(?:\b|[ ·–-])/i.test(String(t.level)))
    : filterLevel==='A2B1' ? allLocal.filter(t=>/A2|B1/i.test(String(t.level)))
    : allLocal;
  const card=t=>{const i=TEXTS.indexOf(t),n=splitSentences(t.text).length;return `<div class="card"><div class="tag">${t.level}</div><h3>${t.title}</h3><p>${t.ru}</p><p class="muted">Большой учебный текст · ${n} предложений</p><button type="button" class="read-text" data-index="${i}">📖 Читать на сайте</button></div>`};
  const hcard=t=>{const i=TEXTS.indexOf(t),n=splitSentences(t.text).length;return `<div class="card real-source-card"><div class="tag">${t.level}</div><h3>${t.title}</h3><p>${t.ru}</p><p class="muted"><b>${n} предложений.</b> Полный оригинальный текст встроен в сайт.</p><p class="source">${t.source}</p><div class="vocab-actions"><button type="button" class="read-text" data-index="${i}">📖 Читать оригинал</button><a class="source-link" href="${t.url}" target="_blank" rel="noopener">Первоисточник ↗</a></div></div>`};
  const filterLabel=filterLevel==='A1'?'A1':filterLevel==='A2B1'?'A2–B1':'Все';
  $('list').innerHTML=`<div class="card library-summary"><h3>Библиотека${filterLevel!=='all'?' — '+filterLabel:''}</h3><p>В этом представлении <b>${local.length} учебных текстов</b>${filterLevel==='all'?` и <b>${historical.length} исторических оригиналов</b>`:''}.</p><p class="muted">Материалы о Суботице находятся отдельно в разделе «🏙 Краеведение».</p><div class="library-filters"><button type="button" class="library-filter ${filterLevel==='all'?'active':''}" data-filter="all">Все</button><button type="button" class="library-filter ${filterLevel==='A1'?'active':''}" data-filter="A1">A1</button><button type="button" class="library-filter ${filterLevel==='A2B1'?'active':''}" data-filter="A2B1">A2–B1</button><button type="button" class="library-filter ${filterLevel==='Исторический'?'active':''}" data-filter="Исторический">Исторические</button></div></div><h3 class="library-heading">📚 Учебные тексты A1/A2–B1</h3><div id="library-local">${local.map(card).join('')}</div><h3 class="library-heading">📜 Исторические оригинальные тексты</h3><p class="muted">Эти произведения встроены локально и открываются прямо в режиме чтения.</p><div id="library-historical" style="${filterLevel==='all'?'':'display:none'}">${historical.map(hcard).join('')}</div>`;
  document.querySelectorAll('.library-filter').forEach(btn=>btn.addEventListener('click',()=>{const f=btn.dataset.filter; if(f==='all') texts('all'); else if(f==='A1') texts('A1'); else if(f==='A2B1') texts('A2B1'); else { $('list').querySelectorAll('.library-filter').forEach(x=>x.classList.remove('active')); btn.classList.add('active'); document.querySelector('#library-local').innerHTML=''; document.querySelector('#library-historical').style.display=''; } }));
}

function openRealSource(i){
  const t=REAL_SOURCES[i];
  window.open(t.url,'_blank','noopener');
}

function tokenize(text){ return text.split(/(\s+)/); }

function splitSentences(text){
  return String(text||'').match(/[^.!?]+[.!?]+|[^.!?]+$/g)?.map(x=>x.trim()).filter(Boolean) || [];
}

async function speakSentenceList(sentences, rate=0.86){
  if(!('speechSynthesis' in window)){ alert('Озвучка не поддерживается этим браузером.'); return; }
  const voice=await getSerbianVoiceReady();
  if(!voice){ alert('На этом устройстве не найден сербский голос. Включи/установи сербский голос в настройках синтеза речи Android.'); return; }
  window.speechSynthesis.cancel(); let i=0;
  const next=()=>{ if(i>=sentences.length) return; const u=new SpeechSynthesisUtterance(sentences[i++]); u.voice=voice; u.lang=voice.lang||'sr-RS'; u.rate=rate; u.pitch=1; u.onend=()=>setTimeout(next,180); window.speechSynthesis.speak(u); }; next();
}

function readerSentenceControls(text){
  return `<div class="reader-audio card">
    <div class="vocab-actions">
      <button type="button" id="speak-full-text">🔊 Озвучить весь текст</button>
      <button type="button" id="speak-sentences">▶ Озвучить по предложениям</button>
      <button type="button" id="speak-slow">🐢 Медленно</button>
      <button type="button" id="stop-speech">⏹ Остановить</button>
      <button type="button" id="text-training">🎯 Тренировать слова этого текста</button>
      <button type="button" id="text-linked-words">📚 Слова этого текста</button>
    </div>
    <div id="text-linked-words-panel" class="text-linked-words-panel"></div>
    <p class="muted small-note">Короткое нажатие на слово — перевод. Нажатие с удержанием на двух словах — словосочетание.</p>
  </div>`;
}

function renderTextLinkedWords(text, open=false){
  const linked=getTextLinkedWords(text);
  const panel=$('text-linked-words-panel');
  const btn=$('text-linked-words');
  if(!panel || !btn)return;
  btn.textContent=`📚 Слова этого текста${linked.length ? ` (${linked.length})` : ''}`;
  if(!linked.length){
    panel.innerHTML='<div class="text-linked-empty">Пока здесь нет слов. Добавляй незнакомые слова через кнопку «Добавить в мои слова» — они останутся закреплены за этим текстом.</div>';
    return;
  }
  const rows=linked.map((w,i)=>{
    const item=saved.find(x=>canonicalWord(x.word)===canonicalWord(w));
    const tr=item?.translation || getTranslation(w);
    return `<div class="text-word-row"><span><b>${escapeHtml(w)}</b><span class="muted"> — ${escapeHtml(tr||'Перевод пока не добавлен')}</span></span><button type="button" class="small text-word-speak" data-word="${escapeHtml(w)}">🔊</button></div>`;
  }).join('');
  panel.innerHTML=`<div class="text-linked-head"><b>Слова этого текста: ${linked.length}</b><button type="button" id="repeat-text-words">🔁 Повторить эти слова</button></div><div class="text-word-list">${rows}</div><p class="muted small-note">Эта подборка хранится отдельно от интервального прогресса «Моих слов» и остаётся за текстом.</p>`;
  panel.classList.toggle('hide', !open);
  $('repeat-text-words')?.addEventListener('click',()=>startTextLinkedTraining(text));
  panel.querySelectorAll('.text-word-speak').forEach(b=>b.addEventListener('click',()=>speakWord(b.dataset.word)));
}
function startTextLinkedTraining(text){
  const linked=getTextLinkedWords(text);
  const pool=linked.map(w=>{
    const item=saved.find(x=>canonicalWord(x.word)===canonicalWord(w));
    return item ? {...item} : {word:w,translation:getTranslation(w),box:1,nextReview:Date.now(),mistakes:0,hard:false};
  }).filter(x=>x.translation && x.translation!=='Перевод пока не добавлен' && x.translation!=='Перевод загружается…');
  if(pool.length<1){alert('В этом тексте пока нет слов с доступным переводом для повторения.');return;}
  exerciseType='choice'; exercisePool=pool; exerciseQueue=shuffle(pool).slice(0,Math.min(20,pool.length)).map(x=>x.word); exerciseIndex=0; renderExercise(); view('review');
}

function renderText(text){
  const raw=String(text||'');
  if(!raw) return '<p class="muted">Текст пока не найден.</p>';
  // Отдельно выделяем слова и пунктуацию. Знак препинания никогда не попадает
  // внутрь кнопки слова, поэтому при выборе последнего слова предложения
  // точка/запятая не становятся частью словосочетания.
  const tokens=raw.match(/\s+|[\p{L}\p{M}\p{N}]+(?:['’][\p{L}\p{M}\p{N}]+)?|[^\s\p{L}\p{M}\p{N}]/gu)||[];
  let wordIndex=0, sentenceIndex=0;
  return tokens.map(part=>{
    if(/^\s+$/.test(part)) return part;
    if(/^[\p{L}\p{M}\p{N}]+(?:['’][\p{L}\p{M}\p{N}]+)?$/u.test(part)){
      const clean=normalize(part);
      return `<button type="button" class="word" data-word="${escapeHtml(clean)}" data-word-index="${wordIndex++}" data-sentence-index="${sentenceIndex}">${escapeHtml(part)}</button>`;
    }
    const punct=escapeHtml(part);
    const closesSentence=/[.!?]/.test(part);
    if(closesSentence) sentenceIndex++;
    return punct;
  }).join('');
}
function openText(i){
  const t = TEXTS[i];
  window.__citajCurrentText = t;
  $("title").textContent = t.title;
  $("level").textContent = `${t.level} · ${t.ru}`;
  // Не выводим техническое описание источника над учебным текстом.
  $("source").textContent = t.level.includes('Исторический') ? t.source : '';
  const textEl=$("text");
  // Сначала гарантированно показываем сам текст. Затем превращаем слова в
  // кликабельные элементы; если браузер встретит неожиданные данные,
  // чтение всё равно не пропадёт целиком.
  const plain=String(t.text||'');
  textEl.textContent=plain;
  try{ textEl.innerHTML=renderText(plain); }
  catch(err){ console.error('renderText error',err); textEl.textContent=plain; }
  document.querySelectorAll('.reader-audio').forEach(x=>x.remove());
  $("popup").classList.add("hide");
  $("text").closest('.card')?.insertAdjacentHTML('afterend', readerSentenceControls(t.text));
  $("popup").insertAdjacentHTML('afterend','<div id="phrase-help" class="phrase-help hide">Первое слово выбрано. Теперь нажми и удерживай второе слово в том же предложении.</div>');
  $("speak-full-text").addEventListener("click",()=>speakText(t.text));
  $("speak-sentences").addEventListener("click",()=>speakSentenceList(splitSentences(t.text),0.86));
  $("speak-slow").addEventListener("click",()=>speakSentenceList(splitSentences(t.text),0.62));
  $("stop-speech").addEventListener("click",()=>window.speechSynthesis?.cancel());
  $("text-training").addEventListener("click",()=>startTextTraining(t.text));
  $("text-linked-words").addEventListener("click",()=>{
    const panel=$('text-linked-words-panel');
    const shouldOpen=panel.classList.contains('hide');
    renderTextLinkedWords(t,shouldOpen);
  });
  renderTextLinkedWords(t,false);

  bindReaderWordInteractions();
  view("reader");
  preloadTextTranslations(t.text).catch(()=>{});
}

let phraseSelection=null;
let suppressWordClickUntil=0;
const wordPressTimers=new WeakMap();

function clearPhraseSelection(){
  phraseSelection=null;
  document.querySelectorAll('.word.phrase-selected').forEach(x=>x.classList.remove('phrase-selected'));
  $('phrase-help')?.classList.add('hide');
}

function beginLongPress(btn){
  cancelLongPress(btn);
  const timer=setTimeout(()=>{
    wordPressTimers.delete(btn);
    suppressWordClickUntil=Date.now()+850;
    const idx=Number(btn.dataset.wordIndex), sentence=Number(btn.dataset.sentenceIndex);
    if(!phraseSelection){
      phraseSelection={firstIndex:idx,sentenceIndex:sentence};
      btn.classList.add('phrase-selected');
      $('phrase-help')?.classList.remove('hide');
      return;
    }
    const first=document.querySelector(`.word[data-word-index="${phraseSelection.firstIndex}"]`);
    const sameSentence=first && Number(first.dataset.sentenceIndex)===sentence;
    if(!sameSentence || first===btn){ clearPhraseSelection(); return; }
    document.querySelectorAll('.word.phrase-selected').forEach(x=>x.classList.remove('phrase-selected'));
    $('phrase-help')?.classList.add('hide');
    finishPhraseSelection(first,btn);
    phraseSelection=null;
  },550);
  wordPressTimers.set(btn,timer);
}

function cancelLongPress(btn){
  const timer=wordPressTimers.get(btn);
  if(timer){clearTimeout(timer);wordPressTimers.delete(btn);}
}

function bindReaderWordInteractions(){
  document.querySelectorAll('.word').forEach(btn=>{
    // Mouse: удержание. Touch: отдельный fallback для Android Chrome, где
    // pointerup/cancel после длительного касания может приходить иначе.
    btn.addEventListener('pointerdown',e=>{
      if(e.pointerType==='touch') return;
      if(e.pointerType==='mouse' && e.button!==0)return;
      beginLongPress(btn);
    });
    btn.addEventListener('pointerup',()=>cancelLongPress(btn));
    btn.addEventListener('pointercancel',()=>cancelLongPress(btn));
    btn.addEventListener('touchstart',e=>{
      if(e.touches.length!==1)return;
      const t=e.touches[0];
      btn.__pressStartX=t.clientX;
      btn.__pressStartY=t.clientY;
      btn.__pressMoved=false;
      beginLongPress(btn);
    },{passive:true});
    btn.addEventListener('touchend',()=>cancelLongPress(btn),{passive:true});
    btn.addEventListener('touchcancel',()=>cancelLongPress(btn),{passive:true});
    btn.addEventListener('touchmove',e=>{
      if(!e.touches.length)return;
      const t=e.touches[0];
      const dx=t.clientX-(btn.__pressStartX||t.clientX);
      const dy=t.clientY-(btn.__pressStartY||t.clientY);
      if(Math.hypot(dx,dy)>12){
        btn.__pressMoved=true;
        cancelLongPress(btn);
      }
    },{passive:true});
    btn.addEventListener('contextmenu',e=>e.preventDefault());
    btn.addEventListener('click',e=>{
      if(Date.now()<suppressWordClickUntil){e.preventDefault();e.stopPropagation();return;}
      word(btn.dataset.word,{
        wordIndex:btn.dataset.wordIndex,
        sentenceIndex:btn.dataset.sentenceIndex,
        sentence:[...document.querySelectorAll('.word[data-sentence-index="'+btn.dataset.sentenceIndex+'"]')].map(x=>x.textContent.trim()).join(' '),
        sourceText: window.__citajCurrentText || null
      });
    });
  });
}
function getSerbianVoice(){
  if(!('speechSynthesis' in window)) return null;
  const voices=window.speechSynthesis.getVoices()||[];
  // Prefer Serbian (Latin) voices, then any Serbian voice. Never silently fall back to English.
  return voices.find(v=>/^sr[-_]RS$/i.test(v.lang))
      || voices.find(v=>/^sr[-_]Latn/i.test(v.lang))
      || voices.find(v=>/^sr[-_]/i.test(v.lang))
      || null;
}
function speechVoicesReady(){
  return new Promise(resolve=>{
    if(!('speechSynthesis' in window)){resolve([]);return;}
    const ready=window.speechSynthesis.getVoices()||[];
    if(ready.length){resolve(ready);return;}
    let done=false;
    const finish=()=>{if(done)return;done=true;window.speechSynthesis.removeEventListener?.('voiceschanged',finish);resolve(window.speechSynthesis.getVoices()||[]);};
    window.speechSynthesis.addEventListener?.('voiceschanged',finish,{once:true});
    setTimeout(finish,1200);
  });
}
async function getSerbianVoiceReady(){
  await speechVoicesReady();
  return getSerbianVoice();
}

async function speakWord(w){
  if (!('speechSynthesis' in window)) {
    alert('Озвучка не поддерживается этим браузером.');
    return;
  }
  const voice=await getSerbianVoiceReady();
  if(!voice){
    alert('На этом устройстве не найден сербский голос. Включи/установи сербский голос в настройках синтеза речи Android. Английский голос использоваться не будет.');
    return;
  }
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(String(w||''));
  u.voice=voice;
  u.lang=voice.lang || 'sr-RS';
  u.rate=0.78;
  u.pitch=1;
  window.speechSynthesis.speak(u);
}

async function speakText(text){
  if (!('speechSynthesis' in window)) {
    alert('Озвучка не поддерживается этим браузером.');
    return;
  }
  const voice=await getSerbianVoiceReady();
  if(!voice){
    alert('На этом устройстве не найден сербский голос. Включи/установи сербский голос в настройках синтеза речи Android. Другой язык подставляться не будет.');
    return;
  }
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(String(text||''));
  u.voice=voice;
  u.lang=voice.lang || 'sr-RS';
  u.rate=0.88;
  u.pitch=1;
  window.speechSynthesis.speak(u);
}

async function remoteVerbInfo(surface){
  const n=normalize(surface);
  if(!n || findVerbInfo(n)) return findVerbInfo(n);
  try{
    const r=await fetch('https://saptac.online/api/word/'+encodeURIComponent(n),{headers:{Accept:'application/json'}});
    if(!r.ok) return null;
    const d=await r.json();
    const pos=String(d?.pos||d?.pos_sr||'').toLowerCase();
    if(!/verb|glagol/.test(pos)) return null;
    const lemma=normalize(d?.lemma||'');
    if(!lemma) return null;
    const base=CANONICAL_VERBS[lemma]||VERB_FORMS[lemma];
    if(base) return base;
    const morph=d?.morphology||{};
    const collect=(rx)=>{const out=[];for(const [k,v] of Object.entries(morph)){if(rx.test(String(k).toLowerCase())){for(const x of Array.isArray(v)?v:[v]){const z=String(x||'').trim();if(z&&!out.includes(z))out.push(z);}}}return out;};
    const pres=collect(/pres|prezent/);
    const past=collect(/past|perf|particip/);
    const fut=collect(/fut|future|futur/);
    const info={lemma,translation:'',past:past.slice(0,4).join(' / '),present:pres.slice(0,4).join(' / '),future:fut.slice(0,4).join(' / '),remote:true};
    if(!info.present && !info.past && !info.future) return null;
    return info;
  }catch(e){return null;}
}

async function word(w, context={} ){
  const requestId=++translationRequestId;
  const translation=getTranslation(w);
  const canonical=canonicalWord(w);
  const exists=saved.some(x=>canonicalWord(x.word)===canonical);
  const sourceText=context.sourceText || null;
  const linked=sourceText ? isWordLinkedToText(sourceText,w) : false;
  let verb=findVerbInfo(w);
  const render=(tr,v=verb)=>{
    if(requestId!==translationRequestId)return;
    const formNote=v&&normalize(w)!==normalize(v.lemma)?`<div class="word-form-note">Форма слова: <b>${escapeHtml(w)}</b> → начальная форма <b>${escapeHtml(v.lemma)}</b></div>`:''; const verbBlock=v?`<div class="verb-block"><div class="verb-title">Глагол: <b>${escapeHtml(v.lemma)}</b> · ${escapeHtml(v.translation||tr)}</div><div class="verb-grid"><div><span>Инфинитив</span><b>${escapeHtml(v.lemma)} <small>— ${escapeHtml(v.translation||tr)}</small></b></div><div><span>Прошедшее</span><b>${escapeHtml(v.past||'—')}</b></div><div><span>Настоящее</span><b>${escapeHtml(v.present||'—')}</b></div><div><span>Будущее</span><b>${escapeHtml(v.future||'—')}</b></div></div></div>`:'';
    const contextBlock=context.sentence?`<div class="word-context"><span>В предложении:</span> ${escapeHtml(context.sentence)}</div>`:'';
    const addLabel = sourceText && linked ? '✓ Уже в словах этого текста' : (exists ? (sourceText ? 'Добавить к словам этого текста' : '✓ Уже в моих словах') : 'Добавить в мои слова');
    $('popup').innerHTML=`<div class="popup-title">${escapeHtml(w)}</div><div class="popup-translation">${escapeHtml(tr)}</div>${formNote}${verbBlock}${contextBlock}<div class="popup-actions"><button type="button" id="speak-word">🔊 Слушать</button><button type="button" id="add-word-button">${addLabel}</button></div>`;
    $('popup').classList.remove('hide');
    $('speak-word').addEventListener('click',()=>speakWord(w));
    const addButton=$('add-word-button');
    if(addButton && !(sourceText && linked)) addButton.addEventListener('click',async()=>{
      const lemma=await addWord(w);
      if(sourceText && lemma) linkWordToText(sourceText,lemma);
      addButton.textContent=sourceText?'✓ Добавлено к словам этого текста':'✓ Сохранено';
      if(sourceText) renderTextLinkedWords(sourceText,true);
    });
  };
  render(translation,verb);
  if(!verb){
    const remoteVerb=await remoteVerbInfo(w);
    if(remoteVerb){
      verb=remoteVerb;
      const lemmaTr=await remoteTranslateWord(remoteVerb.lemma);
      if(requestId===translationRequestId) render(lemmaTr||translation,verb);
    }
  }
  if(translation==='Перевод загружается…'){
    const tr=await remoteTranslateWord(w);
    render(tr,verb);
  }
}
async function finishPhraseSelection(firstBtn,secondBtn){
  const sentenceIndex=firstBtn.dataset.sentenceIndex;
  const sentenceBtns=[...document.querySelectorAll('.word[data-sentence-index="'+sentenceIndex+'"]')];
  const a=Number(firstBtn.dataset.wordIndex), b=Number(secondBtn.dataset.wordIndex);
  const lo=Math.min(a,b), hi=Math.max(a,b);
  const selected=sentenceBtns.filter(x=>{const n=Number(x.dataset.wordIndex); return n>=lo && n<=hi;});
  selected.forEach(x=>x.classList.add('phrase-selected'));
  const cleanPhraseToken=x=>String(x.textContent||'').replace(/^[„“”«»(\[\{]+|[.,!?;:…”»)\]\}]+$/g,'').trim();
  const sr=selected.map(cleanPhraseToken).filter(Boolean).join(' ');
  const sourceTitle=document.getElementById('title')?.textContent||'';
  const sentence=sentenceBtns.map(b=>b.textContent.trim()).join(' ');
  const tr=await translatePhrase(sr);
  $('popup').innerHTML=`<div class="popup-title">🔗 ${escapeHtml(sr)}</div><div class="popup-translation">${escapeHtml(tr)}</div><div class="word-context"><span>Словосочетание из текста:</span> ${escapeHtml(sentence)}</div><div class="popup-actions"><button type="button" id="speak-phrase">🔊 Слушать</button><button type="button" id="save-phrase">Добавить в мои словосочетания</button></div>`;
  $('popup').classList.remove('hide');
  $('speak-phrase').addEventListener('click',()=>speakWord(sr));
  $('save-phrase').addEventListener('click',()=>{const added=addPhrase(sr,tr,sourceTitle,sentence);$('save-phrase').textContent=added?'✓ Сохранено':'✓ Уже сохранено';});
}

const REMOTE_LEMMA_CACHE = (()=>{try{return JSON.parse(localStorage.getItem('citajSrpskiLemmaCacheV1')||'{}')||{};}catch(e){return {};}})();
function saveRemoteLemmaCache(){try{localStorage.setItem('citajSrpskiLemmaCacheV1',JSON.stringify(REMOTE_LEMMA_CACHE));}catch(e){}}
async function remoteLemmaInfo(w){
  const n=normalize(w); if(!n) return null;
  if(REMOTE_LEMMA_CACHE[n]) return REMOTE_LEMMA_CACHE[n];
  try{
    const r=await fetch('https://saptac.online/api/word/'+encodeURIComponent(n),{headers:{Accept:'application/json'}});
    if(!r.ok)return null;
    const d=await r.json();
    const lemma=normalize(d?.lemma||'');
    if(!lemma)return null;
    const info={lemma,pos:String(d?.pos||d?.pos_sr||'').toLowerCase()};
    REMOTE_LEMMA_CACHE[n]=info; saveRemoteLemmaCache(); return info;
  }catch(e){return null;}
}
function mergeSavedWord(oldWord,newWord){
  const oldN=normalize(oldWord), newN=normalize(newWord); if(!newN)return;
  const candidates=saved.filter(x=>normalize(x.word)===oldN || normalize(canonicalWord(x.word))===oldN || normalize(x.word)===newN || normalize(canonicalWord(x.word))===newN);
  if(!candidates.length)return;
  const keep=candidates[0]; keep.word=newN;
  const tr=DICT[newN]||getTranslation(newN); if(tr&&tr!=='Перевод пока не добавлен'&&tr!=='Перевод загружается…')keep.translation=tr;
  for(let i=saved.length-1;i>=0;i--){if(saved[i]!==keep && (normalize(saved[i].word)===oldN || normalize(canonicalWord(saved[i].word))===oldN || normalize(saved[i].word)===newN || normalize(canonicalWord(saved[i].word))===newN)){
    keep.box=Math.max(Number(keep.box)||1,Number(saved[i].box)||1); keep.nextReview=Math.min(Number(keep.nextReview)||Date.now(),Number(saved[i].nextReview)||Date.now()); keep.mistakes=Math.max(Number(keep.mistakes)||0,Number(saved[i].mistakes)||0); saved.splice(i,1);
  }}
}
async function addWord(w){
  const source=normalize(w), localLemma=canonicalWord(source);
  // Сначала пытаемся получить настоящую лемму морфологическим анализом.
  // Если сеть недоступна, безопасная локальная карта остаётся резервом.
  let lemma=localLemma;
  try{
    const remote=await remoteLemmaInfo(source);
    if(remote?.lemma) lemma=normalize(remote.lemma);
  }catch(e){}
  if(!lemma) lemma=localLemma;
  if(!saved.some(x=>canonicalWord(x.word)===lemma || normalize(x.word)===lemma)){
    saved.push({word:lemma,translation:getTranslation(lemma),added:new Date().toISOString(),box:1,nextReview:Date.now(),mistakes:0,hard:false});
  } else {
    // Если такая лемма уже была сохранена под словоформой, приводим её к одной форме.
    mergeSavedWord(source,lemma);
  }
  save();
  return lemma;
}

const PHRASE_PROGRESS_KEY='citajSrpskiPhraseProgressV2';
let phraseProgress={};
try{ phraseProgress=JSON.parse(localStorage.getItem(PHRASE_PROGRESS_KEY)||'{}')||{}; }catch(e){ phraseProgress={}; }
function savePhraseProgress(){try{localStorage.setItem(PHRASE_PROGRESS_KEY,JSON.stringify(phraseProgress));}catch(e){}}
function phraseKey(p){return normalizePhrase(p.sr);}
function phraseMark(p,ok){
  const k=phraseKey(p), st=phraseProgress[k]||{successes:0,attempts:0,dueAt:0};
  st.attempts=(st.attempts||0)+1;
  if(ok){ st.successes=Math.min(3,(st.successes||0)+1); const days=[1,3,7]; st.dueAt=st.successes>=3?Number.MAX_SAFE_INTEGER:Date.now()+days[st.successes-1]*86400000; }
  else { st.dueAt=Date.now()+10*60*1000; }
  phraseProgress[k]=st; savePhraseProgress();
}
let phraseTrainingMode='both';
function startPhraseTraining(mode='both'){
  if(savedPhrases.length<1){alert('Сначала сохрани хотя бы одно словосочетание.');return;}
  phraseTrainingMode=['sr','ru','both'].includes(mode)?mode:'both';
  const due=savedPhrases.filter(p=>{const st=phraseProgress[phraseKey(p)];return !st || (st.successes||0)<3 || Number(st.dueAt)<=Date.now();});
  const active= savedPhrases.filter(p=>{const st=phraseProgress[phraseKey(p)];return !st || (st.successes||0)<3;});
  phraseExerciseQueue=shuffle(due.length?due:active).slice(0,Math.min(20,active.length||due.length));
  if(!phraseExerciseQueue.length){ alert('Сейчас нет словосочетаний для повторения. Все сохранённые словосочетания закреплены на данный момент.'); return; }
  phraseExerciseIndex=0; renderPhraseTraining(); view('review');
}
let phraseExerciseQueue=[], phraseExerciseIndex=0;
function renderPhraseTraining(){
  if(phraseExerciseIndex>=phraseExerciseQueue.length){
    $('review-content').innerHTML='<div class="card"><h2>Тренировка словосочетаний завершена 🎉</h2><p>Ты прошёл '+phraseExerciseQueue.length+' словосочетаний.</p><button type="button" id="phrase-training-back">Вернуться к тренировкам</button></div>';
    $('phrase-training-back').addEventListener('click',training); return;
  }
  const p=phraseExerciseQueue[phraseExerciseIndex], st=phraseProgress[phraseKey(p)]||{successes:0};
  let dir=phraseTrainingMode==='sr'?'sr':phraseTrainingMode==='ru'?'ru':(phraseExerciseIndex%2===0?'sr':'ru');
  const prompt=dir==='sr'?p.sr:p.translation;
  const answer=dir==='sr'?p.translation:p.sr;
  const directionLabel=dir==='sr'?'🇷🇸 Сербский → русский':'🇷🇺 Русский → сербский';
  $('review-content').innerHTML=`<div class="card review-card"><p class="muted">${directionLabel} · Словосочетание ${phraseExerciseIndex+1} из ${phraseExerciseQueue.length} · закреплено ${st.successes||0}/3</p><div class="flash-word phrase-flash">${escapeHtml(prompt)}</div><div class="vocab-actions"><button type="button" id="phrase-answer">Показать ответ</button><button type="button" id="phrase-know" class="hide">✓ Помню</button><button type="button" id="phrase-forget" class="hide">✗ Не помню</button></div><div id="phrase-training-feedback" class="feedback"></div></div>`;
  $('phrase-answer').addEventListener('click',()=>{ $('phrase-training-feedback').innerHTML='<b>'+escapeHtml(answer)+'</b>'; $('phrase-know').classList.remove('hide'); $('phrase-forget').classList.remove('hide'); $('phrase-answer').classList.add('hide'); });
  $('phrase-know').addEventListener('click',()=>{phraseMark(p,true);phraseExerciseIndex++;renderPhraseTraining();});
  $('phrase-forget').addEventListener('click',()=>{phraseMark(p,false);phraseExerciseIndex++;renderPhraseTraining();});
}

